package com.projectdark.mobile;
import static org.junit.Assert.*;
import android.content.*;import android.graphics.*;import com.projectdark.mobile.world.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;import java.util.*;import java.io.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class MagicRecallV251Test {
 final MageSourcesV235Test m=new MageSourcesV235Test();
 @Before public void setup(){m.setup();}
 static void save(Bitmap b,String n)throws Exception{File f=new File("build/reports/horror-v179/v251/"+n+".png");f.getParentFile().mkdirs();try(FileOutputStream o=new FileOutputStream(f)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,o));}}
 @Test public void sorumaFreezesOnlyMonsterAndEveryLivePulseAnchorsToIt()throws Exception{
  GameView v=m.actor(m.mage(25));RuntimeState s=m.h.field(v,"state");RuntimeState.Monster t=s.monsters().get(0);m.tap(v);m.contact(v);assertTrue(s.skillEffects().has(t.id,"FREEZE"));assertTrue(s.skillEffects().disabled(t.id));assertFalse(s.skillEffects().has("player","FREEZE"));assertFalse(s.skillEffects().disabled("player"));SkillVfxRenderer fx=m.h.field(v,"skillVfx");List<SkillVfxRenderer.Pulse> hits=new ArrayList<>();for(SkillVfxRenderer.Pulse p:fx.pulses)if(p.id.equals(m.mage(25))){assertFalse(p.caster);assertEquals(t.id,p.anchor);hits.add(p);}assertEquals(1,hits.size());hits.get(0).age=.25f;m.h.capture(v,"v251-soruma-monster-only");
 }
 @Test public void bothBurstSpellsUseOneFourDirectionSemeliaSequenceAtCorrectLiveCenter()throws Exception{
  ClassicSkillReference ref=new ClassicSkillReference(m.h.c);ClassicSkillReference.Channel source=ref.channel(SkillPolicyV227.SEMELIA,false);
  for(int n:new int[]{35,36}){m.setup();String id=m.mage(n);GameView v=m.actor(id);RuntimeState s=m.h.field(v,"state");RuntimeState.Monster primary=s.monsters().get(0);m.add(s,"extra-recipient",s.player().x-32,s.player().y-16);int hp=s.player().hp;m.tap(v);m.contact(v);assertEquals(0,s.player().mp);assertEquals(hp,s.player().hp);assertTrue(primary.hp<primary.maxHp);SkillVfxRenderer fx=m.h.field(v,"skillVfx");assertEquals(1,fx.pulses.size());SkillVfxRenderer.Pulse p=fx.pulses.get(0);assertEquals("semelia-cross",p.sheet);assertEquals(n==35?"player":primary.id,p.anchor);p.age=source.sequence.duration*.4f;
   SkillVfxRenderer.Anchors a=new SkillVfxRenderer.Anchors(){public float x(String actor){return actor.equals("player")?240:440;}public float y(String actor){return 350;}public float centerY(String actor){return 300;}};Bitmap actual=Bitmap.createBitmap(800,600,Bitmap.Config.ARGB_8888),expected=actual.copy(Bitmap.Config.ARGB_8888,true);fx.draw(new Canvas(actual),a);float x=n==35?240:440;for(int[] d: new int[][]{{32,16},{-32,16},{32,-16},{-32,-16}})ref.drawCentered(new Canvas(expected),source,p.age,x+d[0],300+d[1]);assertTrue("exact four original Semelia copies, no extra fallback",actual.sameAs(expected));save(actual,"four-semelia-"+n);m.h.capture(v,"v251-actual-four-semelia-"+n);fx.tick(source.sequence.duration);assertTrue(fx.pulses.isEmpty());
  }
 }
 @Test public void deathIsRetiredAndOldLearnedQuickslotsAreRemovedWithoutTouchingOtherSkills()throws Exception{
  SkillBook b=SkillBook.load(m.h.c);String death=m.mage(38);assertFalse(b.previewable(death));assertFalse(b.learn(death,100));assertFalse(SkillAbilityCatalog.get(death).supported());assertTrue(b.learn(m.mage(1),100));JSONObject old=b.snapshot();old.getJSONObject("learned").put(death,100);old.getJSONArray("slots").put(0,death);assertTrue(b.restore(old));assertFalse(b.learned(death));assertTrue(b.learned(m.mage(1)));assertTrue(b.snapshot().getJSONArray("slots").isNull(0));
 }
 @Test public void allTenRecallAssetsMatchExactScreenshotPixelsButOnlyFourAreRuntimeItems()throws Exception{
  JSONObject doc=m.doc("recalls-v251/manifest.json");JSONArray rows=doc.getJSONArray("recalls");assertEquals(10,rows.length());SourceItemIconRegistry icons=new SourceItemIconRegistry(m.h.c);RpgProgressionState r=new RpgProgressionState();Bitmap raw=BitmapFactory.decodeFile("../master/source/recalls_v251/reference-rgba.png");int live=0;Bitmap sheet=Bitmap.createBitmap(600,200,Bitmap.Config.ARGB_8888);Canvas out=new Canvas(sheet);
  for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String id=row.getString("id");Bitmap b=icons.get(id);assertNotNull(id,b);JSONArray crop=row.getJSONArray("crop");for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++)assertEquals(id,raw.getPixel(crop.getInt(0)+x,crop.getInt(1)+y),b.getPixel(x,y));out.drawBitmap(b,i%5*120,i/5*100,null);if(row.getBoolean("currentTown")){live++;assertEquals(Integer.valueOf(1),r.inventory().get(id));assertNotNull(r.recallDestination(id));assertSame(b,icons.get(r.itemDefinitions().get(id)));}else{assertFalse(r.itemDefinitions().containsKey(id));assertFalse(r.inventory().containsKey(id));assertNull(r.recallDestination(id));}}
  assertEquals(4,live);save(sheet,"all10-recall-assets");GameView v=new GameView(m.h.c);v.layout(0,0,960,540);RuntimeState s=m.h.field(v,"state");Map<String,Integer> only=new LinkedHashMap<>();for(String id:RecallAssetsV251.LIVE)only.put(id,1);assertTrue(s.rpg().restoreOwnedItems(only,Collections.emptyMap()));m.h.tap(v,742,28);m.h.capture(v,"v251-four-recalls-in-inventory");
 }
 @Test public void recallGrantMigratesOnceAndConsumptionSurvivesRestartWithoutRegrant()throws Exception{
  Context c=m.h.c;SharedPreferences prefs=c.getSharedPreferences("project_dark_f5m_v1",0);GameView v=new GameView(c);RuntimeState s=m.h.field(v,"state");assertTrue(s.rpg().restoreOwnedItems(Collections.emptyMap(),Collections.emptyMap()));F5mSaveStore.saveRewardsActive(s.rpg());prefs.edit().remove("recalls_granted_v251").commit();F5mSaveStore.install(c);GameView upgraded=new GameView(c);RuntimeState us=m.h.field(upgraded,"state");for(String id:RecallAssetsV251.LIVE)assertEquals(Integer.valueOf(1),us.rpg().inventory().get(id));assertEquals(RpgProgressionState.UseResult.USED,us.rpg().useRecall("IT_RECALL_PIET",us));assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView restored=new GameView(c);RuntimeState rs=m.h.field(restored,"state");assertFalse(rs.rpg().inventory().containsKey("IT_RECALL_PIET"));for(String id:new String[]{"IT_RECALL_MILLES","IT_RECALL_ABEL","IT_RECALL_RUCESION"})assertEquals(Integer.valueOf(1),rs.rpg().inventory().get(id));
 }
 @Test public void eachSuppliedExistingTownRecallActuallyTravelsAndConsumesOnce()throws Exception{
  for(String id:RecallAssetsV251.LIVE){m.setup();GameView v=new GameView(m.h.c);v.layout(0,0,960,540);RuntimeState s=m.h.field(v,"state");m.h.call(v,"travelTown",new Class<?>[]{String.class},MineTownGeometry.ID);String destination=s.rpg().recallDestination(id);int before=s.rpg().inventory().get(id);RpgInteractionController inv=m.h.field(v,"rpgInteraction");inv.selectInventoryItem(s.rpg(),id);m.h.call(v,"activateInventoryItem",new Class<?>[]{});assertEquals(id,destination,s.currentMapId());assertEquals(before-1,s.rpg().inventory().getOrDefault(id,0).intValue());m.h.capture(v,"v251-recall-arrival-"+id);}
 }
}
